<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$token=(string)($_GET['token']??'');if($token==='')exit('Portal token required.');$hash=hash('sha256',$token);$s=$db->prepare('SELECT s.*,c.name,c.company FROM client_portal_sessions s JOIN clients c ON c.id=s.client_id WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([$hash]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$db->prepare('UPDATE client_portal_sessions SET last_used_at=NOW() WHERE id=?')->execute([$session['id']]);$p=$db->prepare('SELECT * FROM client_projects WHERE client_id=? ORDER BY created_at DESC');$p->execute([$session['client_id']]);$projects=$p->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between align-items-center"><div><h1 class="h2">Client Portal</h1><p class="text-muted">Welcome, <?=$e($session['name'])?><?=$session['company']?' · '.$e($session['company']):''?></p></div><a class="btn btn-outline-dark" href="billing.php?token=<?=$e(urlencode($token))?>">Billing & Invoices</a></div><?php foreach($projects as $project):$q=$db->prepare('SELECT COUNT(*) total,SUM(status="completed") done FROM project_tasks WHERE project_id=?');$q->execute([$project['id']]);$stat=$q->fetch();$progress=(int)$stat['total']?round(((int)$stat['done']/(int)$stat['total'])*100):0;$a=$db->prepare('SELECT COUNT(*) FROM project_approvals WHERE project_id=? AND status="pending"');$a->execute([$project['id']]);$pending=(int)$a->fetchColumn();?><div class="card mb-4 mt-4"><div class="card-body"><div class="d-flex justify-content-between"><div><h2 class="h5"><?=$e($project['name'])?></h2><div class="text-muted"><?=$e($project['project_number'])?></div></div><span class="badge text-bg-dark"><?=$e(str_replace('_',' ',$project['status']))?></span></div><div class="mt-3"><div class="d-flex justify-content-between"><span>Progress</span><strong><?=$progress?>%</strong></div><div class="progress"><div class="progress-bar" style="width:<?=$progress?>%"></div></div></div><div class="mt-3"><a class="btn btn-dark" href="project.php?token=<?=$e(urlencode($token))?>&id=<?=$project['id']?>">View Project</a><?php if($pending):?><span class="badge text-bg-warning ms-2"><?=$pending?> approval(s) pending</span><?php endif;?></div></div></div><?php endforeach;if(!$projects):?><div class="alert alert-info mt-4">No projects are currently linked to your account.</div><?php endif;?></main></body></html>